function commonFreeSlots(schedules) {
  const blocks = schedules.flat().sort((a, b) => a[0] - b[0])
  const free = []
  if (!blocks.length) return free
  let latestEnd = blocks[0][1]
  for (const [start, end] of blocks) {
    if (start > latestEnd) free.push([latestEnd, start])
    latestEnd = Math.max(latestEnd, end)
  }
  return free
}

