def common_free_slots(schedules):
    blocks = sorted(block for person in schedules for block in person)
    free = []
    if not blocks:
        return free
    latest_end = blocks[0][1]
    for start, end in blocks:
        if start > latest_end:
            free.append([latest_end, start])
        latest_end = max(latest_end, end)
    return free
